draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // draw arms and legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 80);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 30, H/2 + 60);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 30, H/2 + 60);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80);
  ctx.lineTo(W/2 - 20, H/2 + 110);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80);
  ctx.lineTo(W/2 + 20, H/2 + 110);
  ctx.stroke();

  // draw food
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20 + 10 * Math.cos(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100, 20 + 10 * Math.sin(t + Math.PI/2), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
